    def evaluate_tool_calling_accuracy(self, model, test_cases: list) -> float:
        """评估工具调用准确性"""
        # 测试点:
        # 1. 是否选择了正确的工具
        # 2. 工具参数是否准确填写
        # 3. 是否正确处理工具错误并重试
        # 4. 是否避免不必要的工具调用
        correct = 0
        for case in test_cases:
            result = model.invoke(case["input"], tools=case["tools"])
